INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (1, 1, 1, 'Điện thoại iPhone 17', 'iphone-17', NULL, 'iPhone 17', '24990000', '27990000', 'Điện thoại iPhone 17 mới với chip Apple A19 mạnh mẽ, hệ thống camera kép 48 MP tiên tiến và màn hình ProMotion 120Hz mượt mà.', 'Điện thoại iPhone 17 đánh dấu bước tiến mới với chip Apple A19 6 nhân xử lý vượt trội, màn hình OLED Super Retina XDR ProMotion 120Hz 6.3 inch mang lại trải nghiệm vuốt chạm siêu mượt. Hệ thống camera kép phía sau được nâng cấp toàn diện với camera chính 48 MP và camera góc siêu rộng 48 MP, cùng camera trước 18 MP hỗ trợ FaceTime sắc nét. Máy tích hợp sâu Apple Intelligence, chạy iOS 26, hỗ trợ kết nối 5G siêu tốc và thời lượng pin xem video lên đến 27 giờ.', 'active', 1, 'new', 'public', '["apple","iphone","iphone-17","smartphone","new-release"]', '{"display_specs":"OLED 6.3 inch Super Retina XDR, ProMotion (1-120Hz), Dynamic Island","processor_chipset":"Apple A19 6 nhân","graphics_processor":"Apple GPU 5 nhân","ram_capacity":"8GB","storage_capacity":"128GB, 256GB, 512GB","rear_camera":"Chính 48 MP & Góc siêu rộng 48 MP, Zoom quang học 2x","front_camera":"18 MP TrueDepth","battery_capacity":"27 giờ xem video","charging_speed":"Hỗ trợ sạc nhanh 30W trở lên, Sạc không dây MagSafe 25W","operating_system":"iOS 26","network_connectivity":"5G, Wi-Fi 7, Bluetooth 6.0, NFC","sim_slots":"1 Nano SIM & 1 eSIM (Hỗ trợ 2 eSIM)","charging_port":"Type-C","audio_jack":"Không Jack 3.5mm","build_material":"Khung nhôm chuẩn hàng không vũ trụ, Mặt lưng kính pha màu, Mặt trước Ceramic Shield 2","dimensions_weight":"149.6 × 71.5 × 7.95 mm, 177g","release_year":"2025","other_features":"Kháng nước/bụi IP68, Face ID, Apple Intelligence"}', '[{"name":"storage","values":["256GB","512GB"]},{"name":"color","values":["Đen","Trắng","Tím Oải Hương","Xanh Lá Xô Thơm","Xanh Lam Khói"]}]', 0, 0, '4.50', 0, '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-23 19:00:00', '2026-05-01 23:24:11', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (2, 1, 1, 'Điện thoại iPhone 17e', 'iphone-17e', NULL, 'iPhone 17e', '17990000', '19990000', 'Điện thoại iPhone 17e với chip Apple A19, camera 48 MP, màn hình OLED 6.1 inch Super Retina XDR.', 'Điện thoại iPhone 17e được trang bị chip Apple A19 6 nhân, màn hình OLED 6.1 inch Super Retina XDR, camera sau 48 MP, camera trước 12 MP, hỗ trợ 5G, iOS 26 và pin xem video lên đến 26 giờ.', 'active', 1, 'new', 'public', '["apple","iphone","iphone-17e","smartphone"]', '{"display_specs":"OLED 6.1 inch Super Retina XDR","processor_chipset":"Apple A19 6 nhân","graphics_processor":"Apple GPU 4 nhân","ram_capacity":"8GB","storage_capacity":"256GB, 512GB","rear_camera":"48 MP","front_camera":"12 MP","battery_capacity":"26 giờ","charging_speed":"20 W","operating_system":"iOS 26","network_connectivity":"5G","sim_slots":"1 Nano SIM & 1 eSIM","charging_port":"Type-C","audio_jack":"Không Jack 3.5mm","build_material":"Khung nhôm, mặt lưng kính","dimensions_weight":"146.7 × 71.5 × 7.8 mm, 170g","release_year":"2026","other_features":"Apple Intelligence, Face ID, Kháng nước/bụi IP68"}', '[{"name":"storage","values":["256GB","512GB"]},{"name":"color","values":["Hồng nhạt","Đen","Trắng"]}]', 0, 0, '0.00', 0, '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-23 19:00:00', '2026-05-01 23:24:11', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (3, 1, 1, 'Điện thoại iPhone 17 Pro', 'iphone-17-pro', NULL, 'iPhone 17 Pro', '28490000', '30990000', 'Điện thoại iPhone 17 Pro với chip A19 Pro mạnh mẽ, màn hình ProMotion 3000 nits và hệ thống camera Pro Fusion 48MP.', 'Điện thoại iPhone 17 Pro định nghĩa lại đẳng cấp với khung nhôm nguyên khối Unibody, chip Apple A19 Pro (3nm) tối ưu nhiệt độ bằng buồng hơi (Vapor Chamber). Màn hình 6.3 inch sáng kỷ lục 3000 nits phủ Ceramic Shield 2. Hệ thống camera sau 3 ống kính 48MP hỗ trợ zoom quang học tới 8x và camera trước 18MP Center Stage.', 'active', 1, 'new', 'public', '["apple","iphone","iphone-17-pro","smartphone","ios26"]', '{"display_specs":"6.3 inch, OLED Super Retina XDR, 120Hz ProMotion, 3000 nits","processor_chipset":"Apple A19 Pro 6 nhân (Tiến trình 3nm), GPU 6 nhân","graphics_processor":"Apple GPU 6 nhân","ram_capacity":"12GB","storage_capacity":"256GB, 512GB, 1TB","rear_camera":"3x48MP (Chính, Góc siêu rộng, Tele zoom 8x)","front_camera":"18MP Center Stage","battery_capacity":"Xem video lên đến 31 giờ","charging_speed":"Sạc nhanh 40W, sạc không dây MagSafe","operating_system":"iOS 26","network_connectivity":"Wi-Fi 7, 5G (10Gb/s), Bluetooth 6.0","sim_slots":"1 Nano SIM & 1 eSIM","charging_port":"Type-C","audio_jack":"Không Jack 3.5mm","build_material":"Khung nhôm nguyên khối, mặt lưng kính Ceramic Shield","dimensions_weight":"150.0 × 71.9 × 8.75 mm, 206g","release_year":"2025","other_features":"Apple Intelligence, Face ID, Kháng nước/bụi IP68, Camera Control"}', '[{"name":"storage","values":["256GB","512GB","1TB"]},{"name":"color","values":["Bạc","Cam Vũ Trụ","Xanh Đậm"]}]', 0, 0, '0.00', 0, '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-23 19:00:00', '2026-05-01 23:24:11', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (4, 1, 1, 'Điện thoại iPhone 17 Pro Max', 'iphone-17-pro-max', NULL, 'iPhone 17 Pro Max', '37990000', '39990000', 'Điện thoại iPhone 17 Pro Max sở hữu màn hình 6.9 inch lớn nhất từ trước đến nay, bộ 3 camera 48 MP đỉnh cao và chip Apple A19 Pro siêu mạnh mẽ.', 'Điện thoại iPhone 17 Pro Max là phiên bản cao cấp nhất của Apple, nổi bật với màn hình OLED 6.9 inch Super Retina XDR ProMotion 120Hz siêu lớn và độ sáng tối đa lên tới 3000 nits. Máy trang bị chip Apple A19 Pro mang lại hiệu năng dẫn đầu, hệ thống 3 camera sau 48 MP hỗ trợ chụp ảnh chuẩn studio và quay video 4K chuyên nghiệp. Pin cực khủng cho thời lượng xem video lên đến 37 giờ, tích hợp sâu Apple Intelligence, chạy iOS 26 và sạc nhanh công suất 40W.', 'active', 1, 'new', 'public', '["apple","iphone","iphone-17-pro-max","smartphone","flagship"]', '{"display_specs":"OLED 6.9 inch Super Retina XDR (1320 x 2868 Pixels), ProMotion (1-120Hz)","processor_chipset":"Apple A19 Pro","graphics_processor":"Apple GPU","ram_capacity":"12GB","storage_capacity":"256GB, 512GB, 1TB, 2TB","rear_camera":"Bộ 3 camera 48 MP, Zoom quang học","front_camera":"18 MP TrueDepth","battery_capacity":"37 giờ xem video","charging_speed":"Sạc nhanh 40W, Sạc không dây MagSafe","operating_system":"iOS 26","network_connectivity":"5G, Wi-Fi 7, Bluetooth 6.0, NFC","sim_slots":"1 Nano SIM & 1 eSIM (Hỗ trợ 2 eSIM)","charging_port":"Type-C","audio_jack":"Không Jack 3.5mm","build_material":"Khung nhôm nguyên khối & Mặt lưng kính cường lực","dimensions_weight":"163.4 × 78 × 8.75 mm, 233g","release_year":"2025","other_features":"Kháng nước/bụi IP68, Face ID, Nút Điều khiển Camera (Camera Control), Apple Intelligence"}', '[{"name":"storage","values":["256GB","512GB","1TB","2TB"]},{"name":"color","values":["Bạc","Xanh đậm","Cam Vũ Trụ"]}]', 0, 0, '0.00', 0, '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-23 19:00:00', '2026-05-01 23:24:11', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (5, 1, 2, 'Điện thoại Samsung Galaxy A57', 'samsung-galaxy-a57', NULL, 'Samsung Galaxy A57', '12490000', '12990000', 'Điện thoại Samsung Galaxy A57 nổi bật với chip Exynos 1680 8 nhân mạnh mẽ, màn hình Super AMOLED Plus 120Hz mượt mà và bộ 3 camera 50 MP chống rung quang học OIS.', 'Điện thoại Samsung Galaxy A57 mang đến trải nghiệm thị giác tuyệt đỉnh với màn hình 6.7 inch Super AMOLED Plus, độ phân giải Full HD+ cùng tần số quét 120Hz và độ sáng lên tới 1900 nits. Máy sở hữu cấu hình mạnh mẽ nhờ vi xử lý Exynos 1680 và GPU Xclipse 550, đáp ứng mượt mà mọi nhu cầu từ làm việc đến chơi game đồ họa cao. Hệ thống camera vượt trội với camera chính 50 MP hỗ trợ OIS, quay video 4K sắc nét. Cùng viên pin 5000 mAh, sạc siêu nhanh 45W, khung kim loại sang trọng và chuẩn kháng nước IP68, đây là chiếc điện thoại toàn diện trong phân khúc.', 'active', 1, 'new', 'public', '["samsung","galaxy-a","samsung-galaxy-a57","smartphone","android","new-release"]', '{"display_specs":"Super AMOLED Plus 6.7 inch Full HD+ (1080 x 2340 Pixels), 120Hz","processor_chipset":"Exynos 1680 8 nhân","graphics_processor":"Xclipse 550","ram_capacity":"8GB","storage_capacity":"128GB, 256GB","rear_camera":"Chính 50 MP & Phụ 12 MP, 5 MP, Chống rung quang học (OIS)","front_camera":"12 MP","battery_capacity":"5000 mAh","charging_speed":"Sạc siêu nhanh 45W (Super Fast Charging 2.0)","operating_system":"Android 16","network_connectivity":"5G, Wi-Fi 6E, Bluetooth 6.0, NFC","sim_slots":"2 Nano SIM hoặc 1 Nano SIM & 1 eSIM","charging_port":"Type-C","audio_jack":"Không Jack 3.5mm","build_material":"Khung kim loại & Mặt lưng kính cường lực Gorilla Glass Victus+","dimensions_weight":"161.5 × 76.8 × 6.9 mm, 182g","release_year":"2026","other_features":"Kháng nước/bụi IP68, Mở khoá vân tay dưới màn hình, Mở khoá khuôn mặt"}', '[{"name":"storage","values":["128GB (8GB RAM)","256GB (8GB RAM)","256GB (12GB RAM)"]},{"name":"color","values":["Tím ngọc","Xám khói","Xanh đêm (Navy)","Xanh băng"]}]', 0, 0, '0.00', 0, '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-23 19:00:00', '2026-05-01 23:24:11', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (6, 1, 2, 'Điện thoại Samsung Galaxy A37', 'samsung-galaxy-a37', NULL, 'Samsung Galaxy A37', '10290000', NULL, 'Điện thoại Samsung Galaxy A37 nổi bật với chip Exynos 1480 8 nhân mạnh mẽ, màn hình Super AMOLED 120Hz mượt mà và bộ 3 camera 50 MP hỗ trợ chống rung quang học OIS.', 'Điện thoại Samsung Galaxy A37 mang đến trải nghiệm thị giác ấn tượng với màn hình 6.7 inch Super AMOLED, độ phân giải Full HD+ cùng tần số quét 120Hz và độ sáng tối đa 1900 nits. Máy sở hữu cấu hình ổn định nhờ vi xử lý Exynos 1480 và GPU Xclipse 530, đáp ứng mượt mà các nhu cầu làm việc và giải trí hàng ngày. Hệ thống camera chụp ảnh sắc nét với cảm biến chính 50 MP hỗ trợ OIS, quay video 4K chất lượng cao. Cùng viên pin lớn 5000 mAh, sạc siêu nhanh 45W, và chuẩn kháng nước, bụi IP68, đây là chiếc điện thoại toàn diện trong phân khúc tầm trung.', 'active', 1, 'new', 'public', '["samsung","galaxy-a","samsung-galaxy-a37","smartphone","android","new-release"]', '{"display_specs":"Super AMOLED 6.7 inch Full HD+ (1080 x 2340 Pixels), 120Hz, 1900 nits","processor_chipset":"Exynos 1480 8 nhân","graphics_processor":"Xclipse 530","ram_capacity":"6GB","storage_capacity":"128GB, 256GB","rear_camera":"Chính 50 MP & Phụ 8 MP, 5 MP, Chống rung quang học (OIS)","front_camera":"12 MP","battery_capacity":"5000 mAh","charging_speed":"Sạc siêu nhanh 45W (Super Fast Charging 2.0)","operating_system":"Android 16","network_connectivity":"5G, Wi-Fi 6 Dual-band, Bluetooth v5.3, NFC","sim_slots":"2 Nano SIM hoặc 1 Nano SIM & 1 eSIM","charging_port":"Type-C","audio_jack":"Không Jack 3.5mm","build_material":"Khung nhựa & Mặt lưng kính cường lực Gorilla Glass Victus+","dimensions_weight":"162.9 × 78.2 × 7.4 mm, 196g","release_year":"2026","other_features":"Kháng nước/bụi IP68, Mở khoá vân tay dưới màn hình, Mở khoá khuôn mặt"}', '[{"name":"storage","values":["128GB (6GB RAM)","128GB (8GB RAM)","256GB (8GB RAM)"]},{"name":"color","values":["Trắng","Đen","Xanh lá đậm","Tím"]}]', 0, 0, '0.00', 0, '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-23 19:00:00', '2026-05-01 23:24:11', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (7, 1, 3, 'Điện thoại Xiaomi Redmi Note 15 5G', 'xiaomi-redmi-note-15-5g', NULL, 'Xiaomi Redmi Note 15 5G', '7490000', NULL, 'Điện thoại Xiaomi Redmi Note 15 5G sở hữu thiết kế siêu mỏng 7.35mm, màn hình AMOLED cong 120Hz mượt mà, chip Snapdragon 6 Gen 3 và camera 108 MP hỗ trợ chống rung OIS.', 'Điện thoại Xiaomi Redmi Note 15 5G mang đến thiết kế thanh thoát với độ mỏng ấn tượng chỉ 7.35 mm và chuẩn kháng nước, bụi IP66. Máy sở hữu màn hình cong AMOLED 6.77 inch, độ phân giải Full HD+, tần số quét 120Hz và độ sáng tối đa lên đến 3200 nits, cho khả năng hiển thị ngoài trời xuất sắc. Sức mạnh bên trong đến từ vi xử lý Snapdragon 6 Gen 3 cùng hệ điều hành HyperOS 2 mới nhất, đảm bảo hiệu năng đa nhiệm mượt mà. Điểm nhấn nổi bật là hệ thống camera 108 MP "108 MasterPixel Edition" tích hợp OIS, hỗ trợ quay video 4K sắc nét.', 'active', 1, 'new', 'public', '["xiaomi","redmi","redmi-note-15","smartphone","android","5g"]', '{"display_specs":"AMOLED cong 6.77 inch Full HD+, 120Hz, 3200 nits","processor_chipset":"Snapdragon 6 Gen 3 8 nhân (4 nhân 2.4 GHz & 4 nhân 1.8 GHz)","graphics_processor":"Adreno 710","ram_capacity":"6GB","storage_capacity":"128GB, 256GB (Hỗ trợ thẻ nhớ MicroSD)","rear_camera":"108 MP \'108 MasterPixel Edition\', Chống rung quang học (OIS)","front_camera":"20 MP","battery_capacity":"5520 mAh","charging_speed":"Sạc nhanh 45W","operating_system":"Xiaomi HyperOS 2","network_connectivity":"5G, Wi-Fi, Bluetooth","sim_slots":"2 Nano SIM hoặc 1 Nano SIM & 1 MicroSD","charging_port":"Type-C","audio_jack":"Không Jack 3.5mm","build_material":"Khung viền & mặt lưng nhựa Polycarbonate cao cấp","dimensions_weight":"164 x 75.4 x 7.4 mm, 178g","release_year":"2025","other_features":"Kháng nước/bụi IP66, Mở khoá vân tay dưới màn hình, Nhận diện khuôn mặt"}', '[{"name":"storage","values":["128GB (6GB RAM)","256GB (8GB RAM)"]},{"name":"color","values":["Xanh Dương","Đen","Tím"]}]', 0, 0, '0.00', 0, '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-23 19:00:00', '2026-05-01 23:24:11', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (8, 1, 3, 'Điện thoại Xiaomi Redmi Note 15 Pro 5G', 'xiaomi-redmi-note-15-pro-5g', NULL, 'Xiaomi Redmi Note 15 Pro 5G', '10190000', NULL, 'Điện thoại Xiaomi Redmi Note 15 Pro 5G nổi bật với camera 200MP siêu nét, viên pin khủng 6580 mAh công nghệ Silicon-Carbon và chuẩn siêu bền chống rơi 2.5m.', 'Điện thoại Xiaomi Redmi Note 15 Pro 5G mang đến trải nghiệm toàn diện với màn hình AMOLED 6.83 inch độ phân giải 1.5K, tần số quét 120Hz và độ sáng tối đa lên tới 3200 nits. Máy sở hữu hiệu năng mạnh mẽ nhờ vi xử lý MediaTek Dimensity 7400-Ultra và hệ điều hành HyperOS 2.2. Điểm nhấn của sản phẩm là hệ thống camera chính lên đến 200 MP cho độ chi tiết ấn tượng, cùng viên pin "khổng lồ"6580 mAh công nghệ Silicon-Carbon hỗ trợ sạc nhanh 45W. Đặc biệt, máy cực kỳ bền bỉ với kính cường lực Gorilla Glass Victus 2, chuẩn chống nước/bụi IP68, IP69, IP69K và khả năng chống rơi vỡ từ độ cao 2.5m (chứng nhận SGS).', 'active', 1, 'new', 'public', '["xiaomi","redmi","redmi-note-15-pro","smartphone","android","5g"]', '{"display_specs":"AMOLED 6.83 inch 1.5K (1280 x 2772 Pixels), 120Hz, 3200 nits","processor_chipset":"MediaTek Dimensity 7400-Ultra 8 nhân","graphics_processor":"Mali-G615","ram_capacity":"8GB","storage_capacity":"256GB, 512GB","rear_camera":"Chính 200 MP & Phụ 8 MP","front_camera":"20 MP (Hỗ trợ Xóa phông, Làm đẹp AI)","battery_capacity":"6580 mAh (Pin Silicon-Carbon)","charging_speed":"Sạc nhanh TurboCharge 45W, Sạc ngược qua cáp","operating_system":"Xiaomi HyperOS 2.2","network_connectivity":"5G, Wi-Fi 6E, Bluetooth v5.4, NFC, Hồng ngoại","sim_slots":"2 Nano SIM hoặc 1 Nano SIM + 1 eSIM","charging_port":"Type-C","audio_jack":"Không Jack 3.5mm","build_material":"Khung viền & mặt lưng nhựa Polycarbonate cao cấp, Kính cường lực Corning Gorilla Glass Victus 2","dimensions_weight":"163.6 × 78.1 × 7.96 mm, 210g","release_year":"2025","other_features":"Kháng nước/bụi (IP66, IP68, IP69, IP69K), Chống rơi vỡ 2.5m, Mở khoá vân tay dưới màn hình, Nhận diện khuôn mặt"}', '[{"name":"storage","values":["256GB (8GB RAM)","256GB (12GB RAM)","512GB (12GB RAM)"]},{"name":"color","values":["Tím","Titan xám","Đen"]}]', 0, 0, '0.00', 0, '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-23 19:00:00', '2026-05-01 23:24:11', NULL);
