name":"ram","values":["8GB","12GB"]},{"name":"color","values":["Xanh Dương","Trắng"]}]', 0, 0, '0.00', 0, '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-24 17:41:39', '2026-05-01 23:24:11', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (11, 1, 5, 'Điện thoại realme C85', 'realme-c85', NULL, 'realme C85', '5490000', '5690000', 'Điện thoại realme C85 nổi bật với pin siêu khủng 7000 mAh, sạc nhanh 45W cùng màn hình siêu lớn 6.8 inch 144Hz thao tác mượt mà.', 'Điện thoại realme C85 mang hình hài vạm vỡ kết hợp cùng không gian giải trí đỉnh cao nhờ màn hình siêu lớn 6.8 inch IPS LCD cùng tần số quét 144Hz. Điểm ấn tượng nhất là viên pin dung lượng khổng lồ 7000 mAh cho thời lượng sử dụng vượt trội nhiều ngày, đi kèm công nghệ sạc cực nhanh 45W. Về hiệu năng, máy trang bị vi xử lý Snapdragon 685 đa nhiệm mượt mà cùng camera chính 50 MP, kháng nước bụi toàn diện tới IP69K, đáp ứng xuất sắc mọi chu cầu trong phân khúc giá phổ thông.', 'active', 0, 'new', 'public', '["realme","c85","smartphone","4g"]', '{"display_specs":"IPS LCD 6.8 inch HD+ (720 x 1570 Pixels), 144Hz, 1200 nits","processor_chipset":"Snapdragon 685 8 nhân (2 nhân 2.4 GHz & 6 nhân 2 GHz)","graphics_processor":"Adreno 610","ram_capacity":"6GB, 8GB","storage_capacity":"128GB","rear_camera":"Chính 50 MP & Cảm biến Flicker","front_camera":"8 MP","battery_capacity":"7000 mAh, Li-Ion","charging_speed":"45 W","operating_system":"Android 15","network_connectivity":"4G, Wi-Fi 5 (Dual-band), Bluetooth v5.3, GPS","sim_slots":"2 Nano SIM hoặc 1 Nano SIM + 1 thẻ nhớ (MicroSD)","charging_port":"Type-C","audio_jack":"Type-C","build_material":"Khung & Mặt lưng nhựa","dimensions_weight":"Dài 166.18 mm - Ngang 78.03 mm - Dày 8.38 mm - Nặng 212 g","release_year":"2026","other_features":"Kháng nước/bụi IP66/IP68/IP69K, Vân tay cạnh viền, Không gian trẻ em"}', '[{"name":"storage","values":["128GB (6GB RAM)","128GB (8GB RAM)"]},{"name":"color","values":["Xanh dương nhạt","Đen"]}]', 0, 0, '0.00', 0, '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-25 19:15:56', '2026-05-01 23:24:11', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (12, 1, 5, 'Điện thoại realme C85 Pro', 'realme-c85-pro', NULL, 'realme C85 Pro', '6590000', '6990000', 'Điện thoại realme C85 Pro nổi bật với Snapdragon 685, pin khủng 7000 mAh sạc nhanh 45W, màn hình AMOLED 6.8 inch 120Hz siêu sáng 4000 nits, camera chính 50MP, kháng nước, bụi chuẩn IP69 Pro, độ bền chuẩn quân đội MIL-STD 810H.', 'Điện thoại realme C85 Pro là mẫu smartphone bền bỉ đậm chất gaming và giải trí. Máy sở hữu màn hình AMOLED 6.8 inch đạt độ sáng tối đa 4000 nits, tần số quét 120Hz mượt mà cùng kính cường lực AGC DT-Star2. Điểm nhấn là cấu hình Snapdragon 685 kết hợp viên pin cực lớn 7000 mAh hỗ trợ sạc nhanh 45W, tản nhiệt Bionic VC đảm bảo hiệu suất xử lý lâu dài. Về độ bền, máy đạt chuẩn chuẩn quân đội MIL-STD 810H, kháng nước bụi IP69 Pro cùng nhiều tính năng AI đột phá.', 'active', 1, 'new', 'public', '["realme","c85 pro","smartphone","amoled","7000mah"]', '{"display_specs":"AMOLED 6.8 inch Full HD+ (1080 x 2344 Pixels), 120Hz, 4000 nits, Kính cường lực AGC DT-Star2","processor_chipset":"Snapdragon 685 8 nhân (4 nhân 2.8 GHz & 4 nhân 1.9 GHz)","graphics_processor":"Adreno 610","ram_capacity":"8GB","storage_capacity":"128GB, 256GB","rear_camera":"Chính 50 MP & Cảm biến Flicker, Xoá phông, Tilt-shift, Night Mode","front_camera":"8 MP, Xóa phông, HDR, Chụp đêm","battery_capacity":"7000 mAh, Li-Ion","charging_speed":"45 W, Sạc siêu nhanh SuperVOOC, Sạc ngược qua cáp","operating_system":"Android 15","network_connectivity":"4G, Wi-Fi 5 (Dual-band), Bluetooth v5.0, NFC, GPS","sim_slots":"2 Nano SIM, hỗ trợ thẻ nhớ MicroSD","charging_port":"Type-C","audio_jack":"Type-C","build_material":"Khung & Mặt lưng nhựa","dimensions_weight":"Dài 164.4 mm - Ngang 77.99 mm - Dày 8.09 mm - Nặng 205 g","release_year":"2025","other_features":"Kháng nước/bụi IP69 Pro, Độ bền MIL-STD 810H, Mở khoá vân tay dưới màn hình, Tản nhiệt Bionic VC, Các năng AI (Gemini, AI Edit)"}', '[{"name":"storage","values":["128GB (8GB RAM)","256GB (8GB RAM)"]},{"name":"color","values":["Tím","Xanh lá"]}]', 0, 0, '0.00', 0, '{"weight_g":500,"length_cm":20,"width_cm":15,"height_cm":5,"is_fragile":true,"shipping_class":"standard_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-25 19:35:08', '2026-05-01 23:24:11', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (13, 2, 1, 'Máy tính bảng iPad A16 WiFi', 'ipad-a16-wifi', NULL, 'iPad A16 WiFi', '9690000', '9790000', 'Máy tính bảng iPad A16 WiFi với thiết kế siêu mỏng, hiệu năng mạnh mẽ từ chip Apple A16, màn hình Retina IPS LCD 11 inch sắc nét.', 'Máy tính bảng iPad A16 mang đến trải nghiệm tuyệt vời với màn hình Retina IPS LCD 11 inch, chip Apple A16 5 nhân mạnh mẽ xử lý mọi tác vụ từ làm việc đến giải trí. Camera trước và sau đều là 12MP hỗ trợ chụp hình và quay video 4K sắc nét, cùng kết nối mạng Wi-Fi 6 tốc độ cao. Tính năng đặc biệt tích hợp âm thanh Dolby Atmos, ghi âm, quay chụp chuyên nghiệp đem lại cảm giác tối ưu cho người dùng.', 'active', 1, 'new', 'public', '["ipad","máy tính bảng","apple","a16","tablet"]', '{"display_specs":"Retina IPS LCD, 11\\", 1640 x 2360 Pixels, Tần số quét 60 Hz","processor_chipset":"Apple A16 5 nhân","graphics_processor":"Apple GPU 4 nhân","ram_capacity":"6GB","storage_capacity":"128GB, 256GB (Khả dụng khoảng 113GB / 241GB)","rear_camera":"12 MP (Hỗ trợ Smart HDR 4, quay 4K 2160p@60fps, Chế độ điện ảnh, Quay chậm)","front_camera":"12 MP (Góc siêu rộng, Flash Retina, Quay video Full HD, Chế độ điện ảnh)","battery_capacity":"28.93 Wh, Li-Po","charging_speed":"Tối đa 20 W","operating_system":"iPadOS 18","network_connectivity":"Wi-Fi 6, MIMO, Dual-band, Bluetooth v5.3, GPS, iBeacon, Nghe gọi qua FaceTime","sim_slots":"Không","charging_port":"Type-C","audio_jack":"Type-C","build_material":"Nhôm nguyên khối","dimensions_weight":"Dài 248.6 mm - Ngang 179.5 mm - Dày 7 mm - Nặng 477 g","release_year":"03/2025","other_features":"Âm thanh Dolby Atmos, Trung tâm màn hình, Mở khóa vân tay Touch ID, Hỗ trợ bàn phím rời, Hỗ trợ Apple Pencil 1, Micro kép, Có ghi âm"}', '[{"name":"storage","values":["128GB","256GB"]},{"name":"color","values":["Xanh Dương","Bạc","Hồng","Vàng"]}]', 0, 0, '0.00', 0, '{"weight_g":1000,"length_cm":30,"width_cm":20,"height_cm":5,"is_fragile":true,"shipping_class":"medium_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-25 21:47:06', '2026-05-01 23:24:11', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (14, 2, 1, 'Máy tính bảng iPad A16 5G', 'ipad-a16-5g', NULL, 'iPad A16 5G', '13990000', NULL, 'Máy tính bảng iPad A16 5G hỗ trợ tốc độ mạng 5G siêu nhanh, thiết kế cá tính cùng chip Apple A16 mạnh mẽ.', 'Máy tính bảng iPad A16 5G tiếp nối thành công với khả năng kết nối mạng di động 5G cực nhanh, đáp ứng nhu cầu làm việc và giải trí linh hoạt ở mọi nơi. Máy sở hữu màn hình Retina IPS LCD 11 inch sắc nét, vi xử lý Apple A16 5 nhân mạnh mẽ. Cụm camera trước, sau 12MP mang đến chất lượng chụp ảnh và gọi FaceTime chất lượng cao.', 'active', 1, 'new', 'public', '["ipad","máy tính bảng","apple","a16","5g","tablet"]', '{"display_specs":"Retina IPS LCD, 11\\", 1640 x 2360 Pixels, Tần số quét 60 Hz","processor_chipset":"Apple A16 5 nhân","graphics_processor":"Apple GPU 4 nhân","ram_capacity":"6GB","storage_capacity":"128GB, 256GB, 512GB (Khả dụng khoảng 113GB / 241GB / 497GB)","rear_camera":"12 MP (Hỗ trợ Smart HDR 4, quay 4K 2160p@60fps, Chế độ điện ảnh, Quay chậm)","front_camera":"12 MP (Góc siêu rộng, Flash Retina, Quay video Full HD, Chế độ điện ảnh)","battery_capacity":"28.93 Wh, Li-Po","charging_speed":"Tối đa 20 W","operating_system":"iPadOS 18","network_connectivity":"5G, Wi-Fi 6, MIMO, Dual-band, Bluetooth v5.3, GPS, iBeacon, Nghe gọi qua FaceTime","sim_slots":"1 eSIM","charging_port":"Type-C","audio_jack":"Type-C","build_material":"Nhôm nguyên khối","dimensions_weight":"Dài 248.6 mm - Ngang 179.5 mm - Dày 7 mm - Nặng 481 g","release_year":"03/2025","other_features":"Âm thanh Dolby Atmos, Trung tâm màn hình, Mở khóa bằng vân tay Touch ID, Kết nối bàn phím rời, Kết nối Apple Pencil 1, Micro kép, Có ghi âm"}', '[{"name":"storage","values":["128GB","256GB","512GB"]},{"name":"color","values":["Bạc","Vàng","Xanh Dương","Hồng"]}]', 1600, 12000, '0.00', 0, '{"weight_g":1000,"length_cm":30,"width_cm":20,"height_cm":5,"is_fragile":true,"shipping_class":"medium_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-26 02:46:46', '2026-05-01 23:24:11', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (15, 2, 2, 'Máy tính bảng Samsung Galaxy Tab S11 WiFi', 'samsung-galaxy-tab-s11-wifi', NULL, 'Samsung Galaxy Tab S11 WiFi', '20990000', NULL, 'Máy tính bảng Samsung Galaxy Tab S11 WiFi trang bị màn hình 11" 120Hz mượt mà, bút S Pen đa năng cùng hệ sinh thái Galaxy AI thông minh.', 'Máy tính bảng Samsung Galaxy Tab S11 WiFi đem đến trải nghiệm làm việc và giải trí đỉnh cao nhờ thiết kế nhôm nguyên khối, kháng nước đỉnh cao IP68. Ghi dấu với chip MediaTek Dimensity 9400+, dung lượng RAM 12GB mạnh mẽ cùng loạt trợ lý AI (Khoanh tròn tìm kiếm, Note quyền năng, Google Gemini). Hệ thống camera xóa phông AI và âm thanh vòm Dolby Atmos tinh chỉnh bởi AKG sẽ nâng tầm mọi trải nghiệm.', 'active', 1, 'new', 'public', '["samsung","galaxy","tab s11","wifi","máy tính bảng","tablet","ai"]', '{"display_specs":"Dynamic AMOLED 2X, 11\\", 1600 x 2560 Pixels, Tần số quét 120 Hz","processor_chipset":"MediaTek Dimensity 9400+ 8 nhân","graphics_processor":"ARM Immortalis-G925","ram_capacity":"12GB","storage_capacity":"128GB, 256GB","rear_camera":"13 MP (Quay phim 4K 2160p@30fps, Xóa phông, Bộ lọc màu)","front_camera":"12 MP (Xóa phông, Làm đẹp, Bộ lọc màu)","battery_capacity":"8400 mAh, Li-Ion","charging_speed":"Tối đa 45 W","operating_system":"Android 16","network_connectivity":"Wi-Fi 6, Wi-Fi Direct, Dual-band, 6 GHz, Bluetooth v5.4, GPS","sim_slots":"Không","charging_port":"Type-C","audio_jack":"Type-C","build_material":"Nhôm nguyên khối","dimensions_weight":"Dài 165.3 mm - Ngang 253.8 mm - Dày 5.5 mm - Nặng 469 g","release_year":"09/2025","other_features":"Trợ lý AI (Google Gemini, Dịch trực tiếp, Note, Ghi âm), Khoanh tròn tìm kiếm, Xoá vật thể AI, Âm thanh AKG & Dolby Atmos, Samsung DeX, Kết nối bút S Pen, Vân tay dưới MH, IP68"}', '[{"name":"storage","values":["128GB","256GB"]},{"name":"color","values":["Xám","Bạc"]}]', 236, 2000, '0.00', 0, '{"weight_g":1000,"length_cm":30,"width_cm":20,"height_cm":5,"is_fragile":true,"shipping_class":"medium_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-26 03:03:35', '2026-05-01 23:24:11', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (16, 2, 2, 'Máy tính bảng Samsung Galaxy Tab S11 5G', 'samsung-galaxy-tab-s11-5g', NULL, 'Samsung Galaxy Tab S11 5G', '23990000', NULL, 'Máy tính bảng Samsung Galaxy Tab S11 5G siêu tốc với kết nối 5G, màn hình Dynamic AMOLED 2X 120Hz mượt mà và bút S Pen đa năng cùng hệ sinh thái Galaxy AI thông minh.', 'Máy tính bảng Samsung Galaxy Tab S11 5G mang đến cho bạn không gian làm việc và giải trí không giới hạn nhờ kết nối 5G siêu nhanh ở mọi nơi. Ngoại hình cuốn hút với thiết kế nhôm nguyên khối siêu mỏng 5.5mm và kháng nước IP68. Ghi dấu ấn với chip MediaTek Dimensity 9400+, dung lượng RAM 12GB mạnh mẽ cùng loạt trợ lý AI (Khoanh tròn tìm kiếm, Note quyền năng, Dịch trực tiếp). Hệ thống camera AI, âm thanh vòm Dolby Atmos tinh chỉnh bởi AKG luôn sẵn sàng nâng tầm mọi trải nghiệm.', 'active', 1, 'new', 'public', '["samsung","galaxy","tab s11","5g","máy tính bảng","tablet","ai"]', '{"display_specs":"Dynamic AMOLED 2X, 11\\", 1600 x 2560 Pixels, Tần số quét 120 Hz","processor_chipset":"MediaTek Dimensity 9400+ 8 nhân (3.73 GHz)","graphics_processor":"ARM Immortalis-G925","ram_capacity":"12GB","storage_capacity":"128GB, 256GB (Khả dụng khoảng 100.5GB / 224.4GB - Hỗ trợ Micro SD 2TB)","rear_camera":"13 MP (Quay phim 4K 2160p@30fps, Xóa phông, Bộ lọc màu)","front_camera":"12 MP (Xóa phông, Làm đẹp, Bộ lọc màu)","battery_capacity":"8400 mAh, Li-Ion","charging_speed":"Tối đa 45 W","operating_system":"Android 16","network_connectivity":"5G, Wi-Fi 6, Wi-Fi Direct, Dual-band, 6 GHz, Bluetooth v5.4, GPS, QZSS, GLONASS, GALILEO, BDS","sim_slots":"1 Nano SIM & 1 eSIM, Có nghe gọi trực tiếp","charging_port":"Type-C","audio_jack":"Type-C","build_material":"Nhôm nguyên khối","dimensions_weight":"Dài 165.3 mm - Ngang 253.8 mm - Dày 5.5 mm - Nặng 471 g","release_year":"09/2025","other_features":"Trợ lý AI (Dịch trực tiếp, Khoanh tròn tìm kiếm, Biên tập video thông minh), Âm thanh AKG & Dolby Atmos, Samsung DeX, Kết nối bút S Pen, Vân tay dưới màn hình, Kháng nước IP68"}', '[{"name":"storage","values":["128GB","256GB"]},{"name":"color","values":["Xám","Bạc"]}]', 108, 1000, '0.00', 0, '{"weight_g":1000,"length_cm":30,"width_cm":20,"height_cm":5,"is_fragile":true,"shipping_class":"medium_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-26 03:25:09', '2026-05-01 23:24:11', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (17, 2, 2, 'Máy tính bảng Samsung Galaxy Tab S11 Ultra 5G', 'samsung-galaxy-tab-s11-ultra-5g', NULL, 'Samsung Galaxy Tab S11 Ultra 5G', '34990000', NULL, 'Máy tính bảng Samsung Galaxy Tab S11 Ultra 5G với màn hình cực đại 14.6" Dynamic AMOLED 2X, chip Dimensity 9400+, bộ nhớ lên đến 1TB và loạt tính năng Galaxy AI đỉnh cao.', 'Máy tính bảng Samsung Galaxy Tab S11 Ultra 5G là chiếc máy tính bảng mạnh mẽ bậc nhất với màn hình 14.6 inch siêu lớn, thiết kế siêu mỏng 5.1mm. Trang bị chip MediaTek Dimensity 9400+ cùng RAM lên đến 16GB, máy xử lý mượt mà mọi tác vụ chuyên nghiệp. Hệ thống camera AI, pin 11600mAh, bút S Pen thần thánh và khả năng kháng nước IP68 biến đây thành trợ thủ đắc lực cho công việc và sáng tạo.', 'active', 1, 'new', 'public', '["samsung","galaxy","tab s11 ultra","5g","máy tính bảng","tablet","flagship","ai"]', '{"display_specs":"Dynamic AMOLED 2X, 14.6\\", 1848 x 2960 Pixels, Tần số quét 120 Hz","processor_chipset":"MediaTek Dimensity 9400+ 8 nhân (3.73 GHz)","graphics_processor":"ARM Immortalis-G925","ram_capacity":"12GB, 16GB","storage_capacity":"256GB, 1TB (Hỗ trợ Micro SD 2TB)","rear_camera":"Chính 13 MP & Phụ 8 MP (Quay phim 4K 2160p@30fps, Xóa phông, Bộ lọc màu)","front_camera":"12 MP (Xóa phông, Làm đẹp, Bộ lọc màu)","battery_capacity":"11600 mAh, Li-Ion","charging_speed":"Tối đa 45 W","operating_system":"Android 16","network_connectivity":"5G, Wi-Fi 7, Dual-band, 6 GHz, Bluetooth v5.4, GPS, QZSS, GLONASS, GALILEO, BDS","sim_slots":"1 Nano SIM & 1 eSIM, Có nghe gọi trực tiếp","charging_port":"Type-C","audio_jack":"Type-C","build_material":"Nhôm nguyên khối","dimensions_weight":"Dài 208.5 mm - Ngang 326.3 mm - Dày 5.1 mm - Nặng 695 g","release_year":"09/2025","other_features":"Galaxy AI (Xoá vật thể, Trợ lý Note, Google Gemini, Dịch trực tiếp, Biên tập video), Âm thanh AKG & Dolby Atmos, Samsung DeX, Kết nối bút S Pen, Vân tay dưới màn hình, Kháng nước IP68"}', '[{"name":"storage","values":["12GB - 256GB","16GB - 1TB"]},{"name":"color","values":["Xám","Bạc"]}]', 131, 1200, '0.00', 0, '{"weight_g":1000,"length_cm":30,"width_cm":20,"height_cm":5,"is_fragile":true,"shipping_class":"medium_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-26 03:51:13', '2026-05-01 23:24:11', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (18, 2, 3, 'Máy tính bảng Xiaomi Redmi Pad 2 WiFi', 'xiaomi-redmi-pad-2-wifi', NULL, 'Xiaomi Redmi Pad 2 WiFi', '4100000', '5200000', 'Máy tính bảng Xiaomi Redmi Pad 2 WiFi nổi bật với màn hình IPS LCD 11 inch 90Hz mượt mà, vi xử lý Helio G100-Ultra cùng viên pin khủng 9000mAh, mang đến trải nghiệm giải trí trọn vẹn.', 'Máy tính bảng Xiaomi Redmi Pad 2 WiFi là chiếc máy tính bảng giải trí đáng sở hữu trong phân khúc với thiết kế kim loại nguyên khối mỏng nhẹ, sang trọng. Màn hình 11 inch rộng rãi cùng tần số quét 90Hz và hệ thống 4 loa Dolby Atmos cho chất lượng hình ảnh, âm thanh sống động. Hiệu năng ổn định nhờ chip MediaTek Helio G100-Ultra kết hợp nền tảng Xiaomi HyperOS 2 thông minh, tối ưu mượt mà mọi trải nghiệm học tập, làm việc và giải trí.', 'active', 0, 'new', 'public', '["xiaomi","redmi pad 2","wifi","máy tính bảng","tablet","giá rẻ"]', '{"display_specs":"IPS LCD, 11\\", 1600 x 2560 Pixels, Tần số quét 90 Hz","processor_chipset":"MediaTek Helio G100-Ultra 8 nhân (2 nhân 2.2 GHz & 6 nhân 2 GHz)","graphics_processor":"Mali-G57 MC2","ram_capacity":"4GB, 6GB, 8GB","storage_capacity":"128GB, 256GB (Hỗ trợ Micro SD 2TB)","rear_camera":"8 MP (Quay phim FullHD 1080p@30fps, HDR, Quét tài liệu)","front_camera":"5 MP (Quay phim FullHD, Máy nhắc chữ)","battery_capacity":"9000 mAh, Li-Po","charging_speed":"Tối đa 18 W (Sạc kèm máy 15 W)","operating_system":"Xiaomi HyperOS 2","network_connectivity":"Wi-Fi 5, Dual-band, Bluetooth v5.3, GPS","sim_slots":"Không","charging_port":"Type-C","audio_jack":"3.5 mm","build_material":"Kim loại nguyên khối","dimensions_weight":"Dài 254.58 mm - Ngang 166.04 mm - Dày 7.36 mm - Nặng 519 g","release_year":"06/2025","other_features":"Âm thanh Dolby Atmos, 4 loa, Chạm 2 lần sáng màn hình, Đa cửa sổ, Mở khóa bằng khuôn mặt"}', '[{"name":"storage","values":["4GB - 128GB","6GB - 128GB","8GB - 256GB"]},{"name":"color","values":["Xám","Tím","Xanh lá"]}]', 13328, 100000, '0.00', 0, '{"weight_g":1000,"length_cm":30,"width_cm":20,"height_cm":5,"is_fragile":true,"shipping_class":"medium_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-26 13:32:29', '2026-05-01 23:24:11', NULL);
