68, 5000, '0.00', 0, '{"weight_g":1000,"length_cm":30,"width_cm":20,"height_cm":5,"is_fragile":true,"shipping_class":"medium_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-27 01:23:08', '2026-05-01 23:24:11', NULL);
