me":"ram","values":["16GB","24GB"]},{"name":"storage","values":["512GB","256GB"]},{"name":"color","values":["Xanh đen","Bạc","Vàng","Xanh da trời nhạt"]}]', 0, 0, '0.00', 0, '{"weight_g":3000,"length_cm":40,"width_cm":30,"height_cm":10,"is_fragile":true,"shipping_class":"large_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-27 03:43:14', '2026-05-01 23:24:11', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (26, 3, 1, 'Laptop MacBook Air 15 inch M4', 'macbook-air-15-inch-m4', NULL, 'MacBook Air 15 inch M4', '31390000', NULL, 'Laptop MacBook Air 15 inch M4 mới với chip Apple M4 mạnh mẽ, màn hình Liquid Retina 15.3 inch tuyệt đẹp và thiết kế siêu mỏng nhẹ.', 'Laptop MacBook Air 15 inch M4 mang trong mình sức mạnh vượt trội từ chip Apple M4 10 nhân CPU và 10 nhân GPU, cùng bộ nhớ RAM 16GB mặc định giúp xử lý mượt mà mọi tác vụ. Màn hình Liquid Retina 15.3 inch với độ sáng 500 nits, công nghệ True Tone và dải màu rộng (P3) cho trải nghiệm hình ảnh sống động. Máy sở hữu thiết kế vỏ nhôm tái chế 100% siêu mỏng nhẹ chỉ 11.5mm và nặng 1.51kg, thời lượng pin ấn tượng cùng macOS Sequoia mới nhất.', 'active', 1, 'new', 'public', '["macbook","apple","macbook air","macbook m4","laptop cao cấp"]', '{"cpu":"Apple M4 10 nhân (120 GB/s memory bandwidth)","ram":"16 GB (Không hỗ trợ nâng cấp)","hard_drive":"SSD","screen":"15.3\\" Liquid Retina, IPS, Wide color (P3), 500 nits, True Tone, 1 tỷ màu","graphics":"Card tích hợp - 10 nhân GPU","audio":"Hệ thống âm thanh 6 loa, 3 microphones, Dolby Atmos","ports":"MagSafe 3, 2 x Thunderbolt 4.0 (hỗ trợ USB 4, USB Type-C, DisplayPort và Power Delivery)","audio_jack":"3.5 mm","connectivity":"Wi-Fi 6E (802.11ax), Bluetooth 5.3","card_reader":"Không","webcam":"1080p FaceTime HD camera","operating_system":"macOS Sequoia","keyboard_backlight":"Đơn sắc - Màu trắng","security":"Bảo mật vân tay","cooling_system":"Không quạt tản nhiệt","special_features":"Vỏ nhôm tái chế 100%","battery":"Li-Po, 66.5 Wh","dimensions_weight":"Dài 340.4 mm - Rộng 237.6 mm - Dày 11.5 mm - 1.51 kg","build_material":"Nhôm nguyên khối","release_year":"2025"}', '[{"name":"ram","values":["16GB"]},{"name":"storage","values":["256GB","512GB"]},{"name":"color","values":["Xanh đen","Bạc","Vàng","Xanh da trời nhạt"]}]', 0, 0, '0.00', 0, '{"weight_g":3000,"length_cm":40,"width_cm":30,"height_cm":10,"is_fragile":true,"shipping_class":"large_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-27 17:06:00', '2026-05-01 23:24:11', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (27, 3, 6, 'Laptop Asus Vivobook Go 15 E1504FA - NJ776W (R5 7520U, 16GB, 512GB, Full HD, Win11)', 'asus-vivobook-go-15-r5-7520u-16gb-512gb', NULL, 'Asus Vivobook Go 15 E1504FA R5 7520U (NJ776W)', '13490000', '14190000', 'Laptop Asus Vivobook Go 15 E1504FA R5 7520U (NJ776W) là chiếc laptop học tập làm việc bền bỉ chuẩn quân sự, màn hình 15.6" Full HD sắc nét, cùng khả năng mở bản lề 180 độ.', 'Laptop Asus Vivobook Go 15 E1504FA R5 7520U (NJ776W) mang trên mình sức mạnh từ vi xử lý AMD Ryzen 5 7520U, cùng 16GB RAM LPDDR5 tốc độ cao và 512GB SSD NVMe cho trải nghiệm lưu trữ dữ liệu nhanh chóng. Màn hình 15.6 inch Full HD (1920 x 1080) sắc nét kèm công nghệ chống chói ấn tượng. Máy được trang bị nhiều cổng kết nối USB Type-C, HDMI, Wi-Fi 6E, độ bền quân đội MIL STD 810H và bản lề 180 độ mang lại sự linh hoạt đáng kinh ngạc trong một thiết bị chỉ nặng 1.63 kg.', 'active', 0, 'new', 'public', '["asus","asus vivobook","asus vivobook go","laptop sinh viên","laptop văn phòng","laptop giá rẻ"]', '{"cpu":"AMD Ryzen 5 - 7520U (2.80 GHz - 4.30 GHz)","ram":"16 GB LPDDR5 (Onboard, 5500 MHz, Không hỗ trợ nâng cấp)","hard_drive":"512 GB SSD NVMe PCIe (Có thể tháo ra, lắp thanh khác tối đa 1 TB)","screen":"15.6\\" Full HD (1920 x 1080) TN, 60Hz, 45% NTSC, Chống chói Anti Glare, 250 nits","graphics":"Card tích hợp - AMD Radeon Graphics","audio":"SonicMaster audio","ports":"1 x USB 2.0, 1 x USB 3.2, HDMI, USB Type-C","audio_jack":"3.5 mm","connectivity":"Wi-Fi 6E (802.11ax), Bluetooth 5.3","card_reader":"Không","webcam":"HD webcam","operating_system":"Windows 11 Home SL","keyboard_backlight":"Không có đèn","security":"Công tắc khoá camera, Bảo mật vân tay","cooling_system":"Hãng không công bố","special_features":"Độ bền chuẩn quân đội MIL STD 810H, Bản lề mở 180 độ","battery":"3-cell Li-ion, 42 Wh","dimensions_weight":"Dài 360.3 mm - Rộng 232.5 mm - Dày 17.9 mm - 1.63 kg","build_material":"Vỏ nhựa","release_year":"2023"}', '[{"name":"ram","values":["16GB"]},{"name":"storage","values":["512GB"]},{"name":"color","values":["Bạc"]}]', 0, 0, '0.00', 0, '{"weight_g":3000,"length_cm":40,"width_cm":30,"height_cm":10,"is_fragile":true,"shipping_class":"large_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-27 17:30:29', '2026-05-01 23:24:11', NULL);
