1 x USB 2.0, 2 x USB 3.2, HDMI, 1 x USB Type-C (chỉ hỗ trợ Power Delivery)","audio_jack":"3.5 mm","connectivity":"Wi-Fi 6E (802.11ax), Bluetooth 5.3","card_reader":"Không","webcam":"HD webcam","operating_system":"Windows 11 Home SL + Office Home 2024 vĩnh viễn + Microsoft 365 Basic","keyboard_backlight":"Đơn sắc - Màu trắng","security":"Công tắc khoá camera, Bảo mật vân tay","cooling_system":"Hãng không công bố","special_features":"Độ bền chuẩn quân đội MIL STD 810H, Bản lề mở 180 độ","battery":"3-cell Li-ion, 50 Wh","dimensions_weight":"Dài 356.8 mm - Rộng 227.6 mm - Dày 19.9 mm - 1.7 kg","build_material":"Vỏ nhựa","release_year":"2025"}', '[{"name":"ram","values":["16GB"]},{"name":"storage","values":["512GB"]},{"name":"color","values":["Đen"]}]', 0, 0, '0.00', 0, '{"weight_g":3000,"length_cm":40,"width_cm":30,"height_cm":10,"is_fragile":true,"shipping_class":"large_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-03-27 17:59:31', '2026-05-01 23:24:11', NULL);
