INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (46, 4, 1, 'Đồng hồ thông minh Apple Watch Series 11 GPS + Cellular 46mm viền Titanium dây Milan', 'apple-watch-series-11-gps-cellular-46mm-titanium-milan', NULL, 'Apple Watch Series 11 GPS + Cellular 46mm Titanium Milan', '23590000', '23990000', 'Đồng hồ thông minh cao cấp viền Titanium, dây Milan thép không gỉ, chip Apple S10 mạnh hơn 30%, màn hình OLED 2000 nits, hỗ trợ eSIM gọi độc lập và theo dõi sức khỏe toàn diện.', 'Apple Watch Series 11 GPS + Cellular 46mm viền Titanium dây Milan kết hợp thiết kế Titanium cao cấp với dây loop Milan thép không gỉ sang trọng. Sở hữu màn hình OLED 416x496 pixels với độ sáng tối đa 2000 nits, chip S10 cải thiện hiệu năng 30%, bộ nhớ 64GB. Theo dõi sức khỏe toàn diện: ECG, SpO2, phát hiện ngưng thở khi ngủ, cảnh báo huyết áp, theo dõi stress 24h. Hỗ trợ eSIM gọi độc lập, Bluetooth 5.3, WiFi, 5G, GPS đa hệ thống. Pin kéo dài ~24 giờ thông thường, ~38 giờ tiết kiệm. Chống nước 5 ATM, kính Sapphire.', 'active', 1, 'new', 'public', '["apple","apple-watch","series-11","smartwatch","titanium","esim","cellular"]', '{"display_specs":"OLED 416x496 pixels, 46mm, 2000 nits, Always-On Display","processor_chipset":"Apple S10","storage_capacity":"64GB","network_connectivity":"Bluetooth 5.3, WiFi, 5G, eSIM, NFC","battery_capacity":"~24 giờ thông thường, ~38 giờ tiết kiệm","charging_speed":"Đế sạc từ tính","operating_system":"watchOS mới nhất","water_resistance":"5 ATM (ISO 22810:2010)","build_material":"Viền Titanium, kính Sapphire, dây Milan thép không gỉ","dimensions_weight":"46 × 39 × 9.7 mm, 43.1g","sensors":"ECG, SpO2, nhịp tim quang học gen 3, nhiệt độ, khí áp, gia tốc, con quay hồi chuyển, la bàn, ánh sáng, độ sâu","health_features":"ECG, SpO2, huyết áp, ngưng thở khi ngủ, stress 24h, nhịp tim 24h, chu kỳ kinh nguyệt, rụng trứng, phát hiện ngã, phát hiện va chạm, SOS khẩn cấp","sports_modes":"Đi bộ, chạy, bơi, đạp xe, triathlon, golf, yoga, trượt tuyết, chèo thuyền","positioning":"GPS, GLONASS, Galileo, QZSS, BeiDou","sim_slots":"eSIM (gọi độc lập)","compatibility":"iPhone 11 trở lên, iOS 26+","release_year":"2025","other_features":"Always-On Display, Apple Pay, Family Setup, Smart Stack, sạc nhanh, cử chỉ chạm kép"}', '[{"name":"color","values":["Titan xám","Titan vàng","Titan tự nhiên"]}]', 207, 2000, '0.00', 75, '{"weight_g":300,"length_cm":15,"width_cm":15,"height_cm":8,"is_fragile":true,"shipping_class":"small_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-05-16 03:00:00', '2026-05-16 14:34:20', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (47, 4, 1, 'Đồng hồ thông minh Apple Watch Ultra 3 GPS + Cellular 49mm viền Titanium dây Ocean', 'apple-watch-ultra-3-gps-cellular-49mm-titanium-ocean', NULL, 'Apple Watch Ultra 3 GPS + Cellular 49mm Titanium Ocean', '23490000', '23990000', 'Đồng hồ thông minh siêu bền viền Titanium 49mm, dây Ocean cao su, pin 42 giờ (72 giờ tiết kiệm), chống nước 10 ATM chuẩn lặn EN13319, chip S10, màn hình OLED 3000 nits.', 'Apple Watch Ultra 3 GPS + Cellular 49mm viền Titanium dây Ocean là đồng hồ thông minh cao cấp nhất của Apple, thiết kế cho thể thao mạo hiểm và hoạt động ngoài trời. Vỏ Titanium siêu bền, màn hình Sapphire OLED 1.92 inch 422x514 pixels với độ sáng 3000 nits, chip S10 5nm, bộ nhớ 64GB. Chống nước 10 ATM đạt chuẩn EN13319 cho lặn. Pin kéo dài 42 giờ thông thường hoặc 72 giờ chế độ tiết kiệm. Hỗ trợ eSIM gọi độc lập, Bluetooth 5.3, WiFi, 5G. Theo dõi sức khỏe toàn diện với ECG, SpO2, phát hiện ngưng thở, cảnh báo huyết áp.', 'active', 1, 'new', 'public', '["apple","apple-watch","ultra-3","smartwatch","titanium","esim","cellular","diving"]', '{"display_specs":"OLED 1.92 inch, 422x514 pixels, 49mm, 3000 nits, Always-On Display","processor_chipset":"Apple S10 (64-bit, 5nm)","storage_capacity":"64GB","network_connectivity":"Bluetooth 5.3, WiFi 4, 5G, eSIM, NFC","battery_capacity":"~42 giờ thông thường, ~72 giờ tiết kiệm","charging_speed":"Cáp sạc từ tính USB-C, 0-80% trong ~45 phút","operating_system":"watchOS mới nhất","water_resistance":"10 ATM (chuẩn EN13319, hỗ trợ lặn)","build_material":"Viền Titanium, kính Sapphire, dây Ocean cao su","dimensions_weight":"49 × 44 × 12 mm","sensors":"ECG, SpO2, nhịp tim quang học gen 3, nhiệt độ nước, khí áp, gia tốc, con quay hồi chuyển, la bàn, ánh sáng, độ sâu","health_features":"ECG, SpO2, huyết áp, ngưng thở khi ngủ, stress, nhịp tim 24h, chu kỳ kinh nguyệt, phát hiện ngã, phát hiện va chạm, SOS khẩn cấp","sports_modes":"Đi bộ, chạy, bơi, đạp xe, lặn, yoga","positioning":"GPS, GLONASS, Galileo, QZSS, BeiDou","sim_slots":"eSIM (gọi độc lập)","compatibility":"iPhone 11 trở lên, iOS 26+","release_year":"2025","other_features":"Always-On Display, Apple Pay, nút Action, còi báo động 86dB, đo độ sâu khi lặn"}', '[{"name":"color","values":["Titan đen","Titan tự nhiên"]}]', 511, 5000, '0.00', 55, '{"weight_g":300,"length_cm":15,"width_cm":15,"height_cm":8,"is_fragile":true,"shipping_class":"small_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-05-16 03:00:00', '2026-05-16 14:34:20', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (48, 4, 1, 'Đồng hồ thông minh Apple Watch SE 3 GPS 40mm viền nhôm dây thể thao', 'apple-watch-se-3-gps-40mm-nhom-day-the-thao', NULL, 'Apple Watch SE 3 GPS 40mm nhôm dây thể thao', '6790000', '6990000', 'Đồng hồ thông minh giá tốt với chip S10, màn hình OLED Always-On, kính Ion-X, theo dõi sức khỏe toàn diện, phát hiện ngưng thở khi ngủ, chống nước 5 ATM, bộ nhớ 64GB.', 'Apple Watch SE 3 GPS 40mm viền nhôm dây thể thao là lựa chọn giá tốt trong dòng Apple Watch 2025. Chip S10 với Neural Engine 4 nhân, màn hình OLED Always-On 324x394 pixels với kính Ion-X, bộ nhớ 64GB gấp đôi thế hệ trước. Theo dõi sức khỏe: nhịp tim, SpO2, nhiệt độ cổ tay, phát hiện ngưng thở khi ngủ, theo dõi giấc ngủ và chu kỳ kinh nguyệt. Phát hiện ngã, phát hiện va chạm, SOS khẩn cấp. Pin ~18 giờ, sạc nhanh 80% trong 45 phút. Chống nước 5 ATM.', 'active', 1, 'new', 'public', '["apple","apple-watch","se-3","smartwatch","gia-re","nhom"]', '{"display_specs":"OLED 324x394 pixels, 40mm, kính Ion-X cường lực, Always-On Display","processor_chipset":"Apple S10 với Neural Engine 4 nhân","storage_capacity":"64GB","network_connectivity":"Bluetooth 5.3, WiFi, GPS","battery_capacity":"~18 giờ thông thường, ~32 giờ tiết kiệm","charging_speed":"Đế sạc từ tính, 80% trong ~45 phút","operating_system":"watchOS mới nhất","water_resistance":"5 ATM (ISO 22810:2010)","build_material":"Viền nhôm, kính Ion-X, dây silicone thể thao","dimensions_weight":"40 × 34 × 10.7 mm, 26.3g","sensors":"Nhịp tim quang học gen 2, nhiệt độ, khí áp, gia tốc, con quay hồi chuyển, la bàn, ánh sáng","health_features":"Nhịp tim, SpO2, nhiệt độ, ngưng thở khi ngủ, giấc ngủ, chu kỳ kinh nguyệt, stress, phát hiện ngã, phát hiện va chạm, SOS","sports_modes":"Đi bộ, chạy, bơi, đạp xe, yoga","positioning":"GPS, GLONASS, Galileo, QZSS","sim_slots":"Không","compatibility":"iPhone 11 trở lên, iOS 26+","release_year":"2025","other_features":"Always-On Display, Apple Pay, Family Setup, Smart Stack, cử chỉ cổ tay, bản đồ offline"}', '[{"name":"color","values":["Trắng Starlight","Xanh đen"]}]', 0, 0, '0.00', 55, '{"weight_g":300,"length_cm":15,"width_cm":15,"height_cm":8,"is_fragile":true,"shipping_class":"small_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-05-16 03:00:00', '2026-05-16 14:34:20', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (49, 4, 1, 'Đồng hồ thông minh Apple Watch SE 3 GPS 44mm viền nhôm dây thể thao', 'apple-watch-se-3-gps-44mm-nhom-day-the-thao', NULL, 'Apple Watch SE 3 GPS 44mm nhôm dây thể thao', '7690000', '7850000', 'Phiên bản 44mm lớn hơn của Apple Watch SE 3 với chip S10, màn hình OLED Always-On 448x368 pixels, bộ nhớ 64GB, chống nước 5 ATM, theo dõi sức khỏe toàn diện.', 'Apple Watch SE 3 GPS 44mm viền nhôm dây thể thao là phiên bản mặt lớn, phù hợp cổ tay 14-24.5cm. Màn hình OLED 448x368 pixels, chip S10, 64GB bộ nhớ. Theo dõi sức khỏe toàn diện: nhịp tim, SpO2, phát hiện ngưng thở, chu kỳ kinh nguyệt, stress. Phát hiện ngã, phát hiện va chạm, SOS khẩn cấp. Pin ~18 giờ thông thường, ~32 giờ tiết kiệm. Viền nhôm, dây silicone thể thao, chống nước 5 ATM.', 'active', 1, 'new', 'public', '["apple","apple-watch","se-3","smartwatch","44mm","nhom"]', '{"display_specs":"OLED 448x368 pixels, 44mm, kính Ion-X cường lực","processor_chipset":"Apple S10","storage_capacity":"64GB","network_connectivity":"Bluetooth 5.3, WiFi, GPS","battery_capacity":"~18 giờ thông thường, ~32 giờ tiết kiệm","charging_speed":"Đế sạc từ tính","operating_system":"watchOS mới nhất","water_resistance":"5 ATM (ISO 22810:2010)","build_material":"Viền nhôm, kính Ion-X, dây silicone thể thao","dimensions_weight":"44 × 38 × 10.7 mm, 32.9g","sensors":"Nhịp tim quang học gen 2, nhiệt độ, khí áp, gia tốc, con quay hồi chuyển, la bàn, ánh sáng","health_features":"Nhịp tim, SpO2, ngưng thở khi ngủ, giấc ngủ, chu kỳ kinh nguyệt, stress, phát hiện ngã, phát hiện va chạm, SOS","sports_modes":"Đi bộ, chạy, bơi, đạp xe, yoga, HIIT, Pilates","positioning":"GPS, GLONASS, Galileo, QZSS","sim_slots":"Không","compatibility":"iPhone 11 trở lên, iOS 26+","release_year":"2025","other_features":"Apple Pay, Family Setup, Smart Stack, cử chỉ cổ tay, bản đồ offline, Liquid Glass UI"}', '[{"name":"color","values":["Trắng Starlight","Xanh đen"]}]', 0, 0, '0.00', 55, '{"weight_g":300,"length_cm":15,"width_cm":15,"height_cm":8,"is_fragile":true,"shipping_class":"small_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-05-16 03:00:00', '2026-05-16 14:34:20', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (50, 4, 2, 'Đồng hồ thông minh Samsung Galaxy Watch8 40mm dây silicone', 'samsung-galaxy-watch8-40mm-day-silicone', NULL, 'Samsung Galaxy Watch8 40mm dây silicone', '8190000', '8990000', 'Đồng hồ thông minh mỏng nhất dòng Galaxy Watch chỉ 8.6mm, màn hình Super AMOLED 3000 nits, chip Exynos W1000 3nm, cảm biến BioActive 3.0 theo dõi sức khỏe chuyên sâu cùng AI thông minh.', 'Galaxy Watch8 40mm là đồng hồ thông minh mỏng nhất dòng Galaxy Watch với thiết kế squircle chỉ 8.6mm. Vi xử lý Exynos W1000 tiến trình 3nm tăng hiệu năng gấp 3 lần, tiết kiệm pin 30%. Màn hình Super AMOLED 1.34 inch sáng 3000 nits. Cảm biến BioActive 3.0 theo dõi nhịp tim, ECG, huyết áp, SpO2, sức ép mạch máu, chỉ số chống oxy hóa AGEs, thành phần cơ thể. Sleep Coaching phân tích môi trường ngủ, phát hiện ngưng thở. 100+ chế độ thể thao, GPS băng tần kép L1/L5, NFC Samsung Wallet, chống nước 5 ATM, MIL-STD-810H. RAM 2GB, bộ nhớ 32GB, Wear OS 6.', 'active', 1, 'new', 'public', '["samsung","galaxy-watch","watch8","smartwatch","exynos-w1000","bioactive","ai"]', '{"display_specs":"Super AMOLED 1.34 inch, 438x438 pixels, 40mm, 3000 nits, Sapphire Crystal","processor_chipset":"Exynos W1000 (tiến trình 3nm)","storage_capacity":"32GB","network_connectivity":"Bluetooth 5.3, WiFi, NFC, GPS băng tần kép L1/L5","battery_capacity":"325 mAh (~40 giờ tắt AOD)","charging_speed":"Đế sạc từ tính, ~1.1 giờ","operating_system":"Wear OS 6 + One UI Watch 8.0","water_resistance":"5 ATM (IP68, ISO 22810:2010)","build_material":"Khung nhôm nguyên khối, kính Sapphire Crystal, dây silicone","dimensions_weight":"42.7 × 40.4 × 8.6 mm, 30.1g","sensors":"BioActive 3.0 (3-in-1), ánh sáng, khí áp, nhiệt kế hồng ngoại, từ trường, con quay hồi chuyển, gia tốc","health_features":"ECG, huyết áp, SpO2, nhịp tim, sức ép mạch máu, AGEs, thành phần cơ thể, ngưng thở khi ngủ, Sleep Coaching, stress, chu kỳ kinh nguyệt, phát hiện té ngã","sports_modes":"100+ chế độ: đi bộ, nhảy dây, leo núi, chạy bộ, bơi, đạp xe, yoga","positioning":"GPS, GLONASS, Galileo, BeiDou (băng tần kép L1/L5)","sim_slots":"Không","compatibility":"Android 12+ (Google Mobile Services)","release_year":"2025","other_features":"MIL-STD-810H, Samsung Wallet, Always-On Display, phân tích chạy bộ nâng cao"}', '[{"name":"color","values":["Trắng","Xám"]}]', 0, 0, '0.00', 55, '{"weight_g":300,"length_cm":15,"width_cm":15,"height_cm":8,"is_fragile":true,"shipping_class":"small_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-05-16 03:00:00', '2026-05-16 14:34:20', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (51, 4, 2, 'Đồng hồ thông minh Samsung Galaxy Watch7 44mm dây silicone', 'samsung-galaxy-watch7-44mm-day-silicone', NULL, 'Samsung Galaxy Watch7 44mm dây silicone', '5840000', '8340000', 'Đồng hồ thông minh Samsung thế hệ 7 với cảm biến BioActive 2, màn hình Super AMOLED 1.47 inch, chip Exynos W1000, GPS băng tần kép và theo dõi sức khỏe toàn diện.', 'Galaxy Watch7 44mm kết hợp thiết kế tinh tế với theo dõi sức khỏe toàn diện. Cảm biến BioActive 2 đo nhịp tim, ECG, SpO2, huyết áp (cần kết nối điện thoại Samsung). Sleep Coaching, phát hiện té ngã, chỉ số chống oxy hóa AGEs, phân tích thành phần cơ thể. Màn hình Super AMOLED 1.47 inch 480x480 pixels, kính Sapphire Crystal, khung nhôm hợp kim. Chip Exynos W1000, bộ nhớ 32GB. GPS băng tần kép L1/L5, chống nước 5 ATM, MIL-STD-810H. Pin 425mAh ~40 giờ. Samsung Wallet, gợi ý trả lời tin nhắn AI.', 'active', 1, 'new', 'public', '["samsung","galaxy-watch","watch7","smartwatch","exynos-w1000","bioactive"]', '{"display_specs":"Super AMOLED 1.47 inch, 480x480 pixels, 44mm, Sapphire Crystal","processor_chipset":"Exynos W1000","storage_capacity":"32GB","network_connectivity":"Bluetooth 5.3, WiFi, NFC, GPS băng tần kép L1/L5","battery_capacity":"425 mAh (~40 giờ tắt AOD)","charging_speed":"Đế sạc từ tính, ~1.3 giờ","operating_system":"Wear OS tùy biến bởi Samsung","water_resistance":"5 ATM (ISO 22810:2010)","build_material":"Khung nhôm hợp kim, kính Sapphire Crystal, dây silicone","dimensions_weight":"44.4 × 44.4 × 9.7 mm, 33.8g","sensors":"BioActive 2 (3-in-1), ánh sáng, khí áp, nhiệt kế hồng ngoại, từ trường, con quay hồi chuyển, gia tốc","health_features":"ECG, huyết áp, SpO2, nhịp tim, AGEs, thành phần cơ thể, ngưng thở khi ngủ, Sleep Coaching, stress, chu kỳ kinh nguyệt, phát hiện té ngã","sports_modes":"Đi bộ, nhảy dây, leo núi, chạy bộ, bơi, đạp xe, yoga","positioning":"GPS, GLONASS, Galileo, BeiDou (băng tần kép L1/L5)","sim_slots":"Không","compatibility":"Android 11+","release_year":"2024","other_features":"MIL-STD-810H, Samsung Wallet, gợi ý trả lời tin nhắn AI"}', '[{"name":"color","values":["Bạc","Xanh rêu"]}]', 2200, 15000, '4.90', 55, '{"weight_g":300,"length_cm":15,"width_cm":15,"height_cm":8,"is_fragile":true,"shipping_class":"small_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-05-16 03:00:00', '2026-05-16 14:34:20', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (52, 4, 2, 'Đồng hồ thông minh Samsung Galaxy Watch8 Classic 46mm dây da', 'samsung-galaxy-watch8-classic-46mm-day-da', NULL, 'Samsung Galaxy Watch8 Classic 46mm dây da', '10560000', '12990000', 'Đồng hồ thông minh phong cách cổ điển với vòng bezel xoay, viền thép không gỉ, chip Exynos W1000 3nm, màn hình Super AMOLED 3000 nits, cảm biến BioActive 3.0, pin 445mAh 40 giờ.', 'Samsung Galaxy Watch8 Classic 46mm mang thiết kế cổ điển với mặt tròn, vòng bezel xoay vật lý, dây da Eco Hybrid cao cấp. Màn hình Super AMOLED 1.34 inch sáng 3000 nits, kính Sapphire. Chip Exynos W1000 (3nm), RAM 2GB, bộ nhớ 64GB. Cảm biến BioActive 3.0 theo dõi ECG, huyết áp, SpO2, áp lực mạch máu, chỉ số chống oxy hóa AGEs. Pin 445mAh sử dụng ~40 giờ, sạc ~1.2 giờ. Chống nước 5 ATM, MIL-STD-810H. Wear OS 6 + One UI Watch 8.0.', 'active', 1, 'new', 'public', '["samsung","galaxy-watch","watch8-classic","smartwatch","bezel","classic"]', '{"display_specs":"Super AMOLED 1.34 inch, 438x438 pixels, 46mm, 3000 nits, Sapphire Crystal","processor_chipset":"Exynos W1000 (tiến trình 3nm)","storage_capacity":"64GB (RAM 2GB)","network_connectivity":"Bluetooth 5.3, WiFi, NFC","battery_capacity":"445 mAh (~40 giờ)","charging_speed":"Đế sạc từ tính, ~1.2 giờ","operating_system":"Wear OS 6 + One UI Watch 8.0","water_resistance":"5 ATM (ISO 22810:2010)","build_material":"Viền thép không gỉ, kính Sapphire, dây da Eco Hybrid","dimensions_weight":"46.5 × 46 × 10.6 mm, 63.5g","sensors":"BioActive 3.0 (3-in-1), ánh sáng, khí áp, nhiệt độ, địa từ, con quay hồi chuyển, gia tốc","health_features":"ECG, huyết áp, SpO2, áp lực mạch máu, AGEs, thành phần cơ thể, giấc ngủ, stress, phát hiện té ngã, chu kỳ kinh nguyệt","sports_modes":"100+ chế độ: đi bộ, chạy bộ, bơi, đạp xe, yoga, leo núi","positioning":"GPS, GLONASS, Galileo, BeiDou (băng tần kép L1/L5)","sim_slots":"Không","compatibility":"Android 12+","release_year":"2025","other_features":"MIL-STD-810H, vòng bezel xoay, Samsung Wallet, Always-On Display"}', '[{"name":"color","values":["Trắng","Đen"]}]', 0, 0, '0.00', 55, '{"weight_g":200,"length_cm":12,"width_cm":12,"height_cm":8,"is_fragile":true,"shipping_class":"small_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-05-16 05:00:00', '2026-05-16 14:34:20', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (53, 4, 3, 'Vòng đeo tay thông minh Mi Band 10 viền nhôm', 'mi-band-10-vien-nhom', NULL, 'Xiaomi Mi Band 10 viền nhôm', '970000', '1170000', 'Vòng đeo tay thông minh màn hình AMOLED 1.72 inch, pin 21 ngày, chống nước 5 ATM, 150+ chế độ luyện tập, viền hợp kim nhôm siêu nhẹ 15.95g.', 'Xiaomi Mi Band 10 sở hữu màn hình AMOLED 1.72 inch 212x520 pixels, độ sáng 1500 nits. Viền hợp kim nhôm, dây TPU kháng khuẩn, siêu nhẹ chỉ 15.95g. 150+ chế độ luyện tập, theo dõi sức khỏe 24/7 (nhịp tim, SpO2, giấc ngủ, stress), hệ thống PAI. Pin 233mAh sử dụng 21 ngày (cơ bản) hoặc 9 ngày (Always On Display). Bluetooth 5.4, chống nước 5 ATM. HyperOS, tương thích Android 8.0+ và iOS 12+.', 'active', 1, 'new', 'public', '["xiaomi","mi-band","mi-band-10","smartwatch","vong-tay","gia-re"]', '{"display_specs":"AMOLED 1.72 inch, 212x520 pixels, 1500 nits","processor_chipset":"Hãng không công bố","storage_capacity":"Hãng không công bố","network_connectivity":"Bluetooth 5.4","battery_capacity":"233 mAh (~21 ngày cơ bản, ~9 ngày AOD)","charging_speed":"Dây sạc nam châm, ~1 giờ","operating_system":"HyperOS","water_resistance":"5 ATM","build_material":"Viền hợp kim nhôm, kính cường lực 2.5D, dây TPU kháng khuẩn","dimensions_weight":"46.57 × 22.54 × 10.95 mm, 15.95g","sensors":"Nhịp tim PPG, ánh sáng, từ, con quay hồi chuyển, gia tốc, la bàn","health_features":"SpO2, nhịp tim 24h, PAI, giấc ngủ, stress, chu kỳ kinh nguyệt, bước chân, calories, bài tập thở","sports_modes":"150+ chế độ: đi bộ, chạy bộ, đạp xe, bơi, yoga","positioning":"Không (dùng GPS điện thoại)","sim_slots":"Không","compatibility":"Android 8.0+, iOS 12+","release_year":"2025","other_features":"Always-On Display, đèn pin, điều khiển chụp ảnh/nhạc, tìm điện thoại, thay mặt đồng hồ"}', '[{"name":"color","values":["Đen","Bạc","Hồng"]}]', 0, 0, '0.00', 115, '{"weight_g":200,"length_cm":12,"width_cm":12,"height_cm":8,"is_fragile":true,"shipping_class":"small_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-05-16 05:00:00', '2026-05-16 14:34:20', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (54, 4, 3, 'Đồng hồ thông minh Xiaomi Redmi Watch 5 47.5mm dây TPU', 'xiaomi-redmi-watch-5-47-5mm-day-tpu', NULL, 'Xiaomi Redmi Watch 5 47.5mm dây TPU', '2540000', '2940000', 'Đồng hồ thông minh màn hình AMOLED 2.07 inch sắc nét, pin 24 ngày, GPS độc lập, nghe gọi trực tiếp, 150+ chế độ thể thao, chống nước 5 ATM.', 'Xiaomi Redmi Watch 5 sở hữu màn hình AMOLED 2.07 inch 432x514 pixels, độ sáng 1500 nits. Khung hợp kim nhôm, dây TPU. Theo dõi sức khỏe toàn diện (SpO2, nhịp tim, giấc ngủ, stress), hỗ trợ nghe gọi trực tiếp trên đồng hồ. GPS độc lập đa hệ thống, 150+ chế độ thể thao. Pin 550mAh sử dụng ~24 ngày, chống nước 5 ATM. HyperOS 2.0, Bluetooth 5.3.', 'active', 1, 'new', 'public', '["xiaomi","redmi-watch","redmi-watch-5","smartwatch","gps","nghe-goi"]', '{"display_specs":"AMOLED 2.07 inch, 432x514 pixels, 1500 nits","processor_chipset":"Hãng không công bố","storage_capacity":"512 MB","network_connectivity":"Bluetooth 5.3","battery_capacity":"550 mAh (~24 ngày tắt AOD)","charging_speed":"Dây sạc nam châm, ~1.5 giờ","operating_system":"HyperOS 2.0","water_resistance":"5 ATM (ISO 22810:2010)","build_material":"Khung hợp kim nhôm, kính cường lực, dây TPU","dimensions_weight":"47.5 × 41.1 × 11.3 mm, 33.5g","sensors":"Nhịp tim, ánh sáng, gia tốc, la bàn điện tử, SpO2","health_features":"SpO2, nhịp tim 24h, giấc ngủ, stress, nhịp thở, chu kỳ kinh nguyệt, cảnh báo nhịp tim cao/thấp, bước chân, calories","sports_modes":"150+ chế độ: đi bộ, nhảy dây, leo núi, chạy bộ, đạp xe, yoga, bơi","positioning":"GPS, GLONASS, Galileo, QZSS, BeiDou","sim_slots":"Không","compatibility":"Android 8.0+, iOS 12+","release_year":"2024","other_features":"Always-On Display, nghe gọi trên đồng hồ (loa + mic), điều khiển chụp ảnh/nhạc, tìm điện thoại"}', '[{"name":"color","values":["Đen","Bạc","Tím"]}]', 0, 0, '0.00', 125, '{"weight_g":200,"length_cm":12,"width_cm":12,"height_cm":8,"is_fragile":true,"shipping_class":"small_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-05-16 05:00:00', '2026-05-16 14:34:20', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (55, 4, 3, 'Đồng hồ thông minh Xiaomi Redmi Watch 5 Lite 48.2mm dây TPU', 'xiaomi-redmi-watch-5-lite-48-2mm-day-tpu', NULL, 'Xiaomi Redmi Watch 5 Lite 48.2mm dây TPU', '1190000', '1370000', 'Đồng hồ thông minh màn hình AMOLED 1.96 inch, pin 18 ngày, GPS độc lập, nghe gọi trực tiếp, 150+ chế độ thể thao, chống nước 5 ATM, giá phải chăng.', 'Xiaomi Redmi Watch 5 Lite sở hữu màn hình AMOLED 1.96 inch 410x502 pixels. Dây TPU thoải mái, HyperOS, Bluetooth 5.3. 150+ chế độ luyện tập với GPS độc lập đa hệ thống. Theo dõi sức khỏe: nhịp tim, SpO2, giấc ngủ, stress, chu kỳ kinh nguyệt. Nghe gọi trực tiếp với mic và loa kép. Pin 470mAh sử dụng tới 18 ngày (cơ bản) hoặc 7 ngày (Always On). Chống nước 5 ATM.', 'active', 1, 'new', 'public', '["xiaomi","redmi-watch","redmi-watch-5-lite","smartwatch","gia-re","gps"]', '{"display_specs":"AMOLED 1.96 inch, 410x502 pixels, kính cường lực Panda","processor_chipset":"Sifli SF32LB523","storage_capacity":"4 GB","network_connectivity":"Bluetooth 5.3","battery_capacity":"470 mAh (~18 ngày cơ bản, ~7 ngày AOD)","charging_speed":"Dây sạc nam châm, ~2 giờ","operating_system":"HyperOS","water_resistance":"5 ATM (ISO 22810:2010)","build_material":"Khung nhựa, kính cường lực Panda, dây TPU","dimensions_weight":"48.2 × 39.3 × 10.6 mm, 29.2g","sensors":"Nhịp tim, con quay hồi chuyển, gia tốc, SpO2","health_features":"SpO2, nhịp tim 24h, giấc ngủ, stress, nhịp thở, chu kỳ kinh nguyệt, cảnh báo nhịp tim cao/thấp, bước chân","sports_modes":"150+ chế độ: đi bộ, nhảy dây, leo núi, chạy bộ, đạp xe, yoga, cầu lông, bóng rổ, chèo thuyền","positioning":"GPS, GLONASS, Galileo, QZSS, BeiDou","sim_slots":"Không","compatibility":"Android 8.0+, iOS 12+","release_year":"2024","other_features":"Always-On Display, nghe gọi trên đồng hồ (loa + mic kép), trợ lý giọng nói, SOS, đèn pin"}', '[{"name":"color","values":["Đen","Vàng"]}]', 0, 0, '0.00', 100, '{"weight_g":200,"length_cm":12,"width_cm":12,"height_cm":8,"is_fragile":true,"shipping_class":"small_electronic","free_shipping":false,"contains_battery":true,"requires_insurance":true}', NULL, NULL, NULL, '2026-05-16 05:00:00', '2026-05-16 14:34:20', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (56, 5, 11, 'Đồng hồ CASIO 30.2 mm Unisex A158WA-1DF', 'casio-a158wa-1df-unisex', NULL, 'CASIO A158WA-1DF', '555000', '1014000', 'Đồng hồ Casio cổ điển phong cách Vintage Nhật Bản, pin 7 năm, chống nước 3 ATM, thiết kế Unisex nhỏ gọn 30.2mm.', 'Đồng hồ CASIO A158WA-1DF thuộc bộ sưu tập Vintage, thiết kế Unisex với đường kính mặt 30.2mm. Khung viền nhựa PC kết hợp dây hợp kim nhẹ và bền. Chống nước 3 ATM phù hợp rửa tay, đi mưa. Trang bị báo thức, đèn nền LED, lịch ngày - thứ. Bộ máy Quartz pin khoảng 7 năm.', 'active', 1, 'new', 'public', '["casio","vintage","unisex","dong-ho","gia-re","nhat-ban"]', '{"brand_origin":"Nhật Bản","target_user":"Unisex","collection":"Vintage","dial_size":"30.2 mm","case_thickness":"9.2 mm","band_width":"14.8 mm","band_material":"Hợp kim","case_material":"Nhựa PC","glass_material":"Nhựa","movement_type":"Pin (Quartz)","power_source":"Pin","battery_life":"Khoảng 7 năm","water_resistance":"3 ATM - Rửa tay, đi mưa","features":"Báo thức, Đèn nền LED, Lịch ngày - thứ","made_in":"Nhật Bản/Thái Lan/Trung Quốc (tùy lô)","release_year":"2019","movement_name":"Hãng không công bố","power_reserve":"Không (dùng pin)"}', '[{"name":"color","values":["Bạc"]}]', 0, 0, '0.00', 50, '{"weight_g":300,"length_cm":15,"width_cm":10,"height_cm":8,"is_fragile":true,"shipping_class":"small_accessory","free_shipping":false,"contains_battery":false,"requires_insurance":true}', NULL, NULL, NULL, '2026-05-16 05:00:00', '2026-05-16 14:34:20', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (57, 5, 11, 'Đồng hồ CASIO Timeless 36.8 mm Nam W-800H-1AVDF', 'casio-w-800h-1avdf-nam', NULL, 'CASIO W-800H-1AVDF', '861000', '1014000', 'Đồng hồ Casio thể thao nam, chống nước 10 ATM tắm bơi được, pin 10 năm, bấm giờ thể thao, đèn nền LED.', 'Đồng hồ nam CASIO W-800H-1AVDF thuộc bộ sưu tập Timeless, kiểu dáng thể thao phù hợp nam giới năng động. Vỏ nhựa Resin nhỏ gọn, mặt kính trong suốt chống trầy. Bấm giờ thể thao với split time, báo thức hàng ngày, đèn nền LED. Dây đeo đục lỗ nhẹ nhàng. Chống nước 10 ATM có thể tắm và bơi. Pin khoảng 10 năm.', 'active', 1, 'new', 'public', '["casio","timeless","nam","dong-ho","the-thao","chong-nuoc"]', '{"brand_origin":"Nhật Bản","target_user":"Nam","collection":"Timeless","dial_size":"36.8 mm","case_thickness":"12.5 mm","band_material":"Nhựa","case_material":"Nhựa Resin","glass_material":"Nhựa Resin","movement_type":"Pin (Quartz)","power_source":"Pin","battery_life":"Khoảng 10 năm","water_resistance":"10 ATM - Tắm, bơi lội","features":"Báo thức, Bấm giờ thể thao, Đèn nền LED","made_in":"Nhật Bản/Thái Lan/Trung Quốc (tùy lô)","release_year":"2019","band_width":"Hãng không công bố","movement_name":"Hãng không công bố","power_reserve":"Không (dùng pin)"}', '[{"name":"color","values":["Đen"]}]', 0, 0, '0.00', 50, '{"weight_g":300,"length_cm":15,"width_cm":10,"height_cm":8,"is_fragile":true,"shipping_class":"small_accessory","free_shipping":false,"contains_battery":false,"requires_insurance":true}', NULL, NULL, NULL, '2026-05-16 05:00:00', '2026-05-16 14:34:20', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (58, 5, 12, 'Đồng hồ CITIZEN 39 mm Nam BI5006-81L', 'citizen-bi5006-81l-nam', NULL, 'CITIZEN BI5006-81L', '3727000', '4385000', 'Đồng hồ Citizen nam Quartz mặt xanh, khung thép không gỉ sáng bóng, kính khoáng Mineral, chống nước 5 ATM, dây hợp kim.', 'Đồng hồ CITIZEN BI5006-81L thương hiệu Nhật Bản uy tín. Khung viền thép không gỉ bền bỉ, chống oxy hóa và ăn mòn. Mặt kính khoáng Mineral trong suốt, độ cứng cao. Chống nước 5 ATM phù hợp tắm và đi mưa. Trang bị lịch ngày. Dây hợp kim bền bỉ, mát tay. Bộ máy Quartz pin khoảng 2 năm.', 'active', 1, 'new', 'public', '["citizen","nam","dong-ho","quartz","nhat-ban","mat-xanh"]', '{"brand_origin":"Nhật Bản","target_user":"Nam","dial_size":"39 mm","band_width":"21 mm","band_material":"Hợp kim","case_material":"Thép không gỉ","glass_material":"Kính khoáng Mineral","movement_type":"Pin (Quartz)","power_source":"Pin","battery_life":"Khoảng 2 năm","water_resistance":"5 ATM - Đi mưa, tắm","features":"Lịch ngày","made_in":"Nhật Bản/Thái Lan/Trung Quốc (tùy lô)","release_year":"2019","collection":"Hãng không công bố","case_thickness":"Hãng không công bố","movement_name":"Hãng không công bố","power_reserve":"Không (dùng pin)"}', '[{"name":"color","values":["Xanh"]}]', 0, 0, '0.00', 30, '{"weight_g":300,"length_cm":15,"width_cm":10,"height_cm":8,"is_fragile":true,"shipping_class":"small_accessory","free_shipping":false,"contains_battery":false,"requires_insurance":true}', NULL, NULL, NULL, '2026-05-16 05:00:00', '2026-05-16 14:34:20', NULL);
INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_vi`, `slug`, `base_name`, `model`, `base_price`, `compare_at_price`, `short_description_vi`, `description_vi`, `status`, `is_featured`, `condition`, `visibility`, `tags`, `specifications`, `attributes`, `sold_count`, `view_count`, `rating_average`, `stock_quantity`, `shipping_info`, `seo_title_vi`, `seo_description_vi`, `seo_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES (59, 5, 12, 'Đồng hồ CITIZEN 42 mm Nam NH8350-08A', 'citizen-nh8350-08a-nam', NULL, 'CITIZEN NH8350-08A', '4426000', '6385000', 'Đồng hồ cơ tự động Citizen nam, bộ máy Caliber 8200, vỏ thép không gỉ, kính Mineral, dây da tổng hợp, lịch ngày + thứ, chống nước 5 ATM.', 'Đồng hồ CITIZEN NH8350-08A bộ máy cơ tự động (Automatic) Caliber 8200, không lo hết pin. Vỏ thép không gỉ bền bỉ, mặt kính khoáng Mineral chịu va đập. Lịch ngày và lịch thứ tiện lợi. Chống nước 5 ATM. Dây da tổng hợp đeo thoải mái, khóa cài thép không gỉ. Thời gian trữ cót khoảng 24 tiếng.', 'active', 1, 'new', 'public', '["citizen","nam","dong-ho","automatic","co-tu-dong","nhat-ban"]', '{"brand_origin":"Nhật Bản","target_user":"Nam","collection":"Mechanical","dial_size":"42 mm","case_thickness":"11.2 mm","band_width":"20 mm","band_material":"Da tổng hợp","case_material":"Thép không gỉ","glass_material":"Kính khoáng Mineral","movement_name":"Caliber 8200","movement_type":"Cơ tự động (Automatic)","power_source":"Cơ tự động","power_reserve":"Khoảng 24 tiếng","water_resistance":"5 ATM - Đi mưa, tắm","features":"Lịch ngày, Lịch thứ","made_in":"Nhật Bản/Thái Lan/Trung Quốc (tùy lô)","release_year":"2019","battery_life":"Không (cơ tự động)"}', '[{"name":"color","values":["Trắng"]}]', 0, 0, '0.00', 20, '{"weight_g":300,"length_cm":15,"width_cm":10,"height_cm":8,"is_fragile":true,"shipping_class":"small_accessory","free_shipping":false,"contains_battery":false,"requires_insurance":true}', NULL, NULL, NULL, '2026-05-16 05:00:00', '2026-05-16 14:34:20', NULL);
